import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        vm.assume(newOwner != address(0));
        vm.prank(actor);
        try c.setOwner(newOwner) returns (bool success) {
            assertTrue(actor == tx.origin && address(actor) != address(0));
        } catch {
            assertTrue(true);
        }
    }
}

